{
  "spec": "Create a 3-stage shift register using three 8-bit D flip-flops (my_dff8). The 2-bit sel signal selects the number of clock cycles of delay applied to the input d before it appears at output q: 0 cycles (q = d), 1 cycle (q = first flip-flop output), 2 cycles (q = second flip-flop output), or 3 cycles (q = third flip-flop output). The provided my_dff8 module is a positive-edge-triggered D flip-flop with 8-bit data input and output.",
  "given_sv": "module my_dff8(input clk, input [7:0] d, output [7:0] q);
  always @(posedge clk) q <= d;
endmodule",
  "ref_sv": "module RefModule(input clk, input [7:0] d, input [1:0] sel, output [7:0] q);
  reg [7:0] stage1, stage2, stage3;
  always @(posedge clk) begin
    stage1 <= d;
    stage2 <= stage1;
    stage3 <= stage2;
  end
  always @(*) begin
    case (sel)
      2'd0: q = d;
      2'd1: q = stage1;
      2'd2: q = stage2;
      2'd3: q = stage3;
    endcase
  end
endmodule",
  "solution_sv": "module top_module(input clk, input [7:0] d, input [1:0] sel, output [7:0] q);
  wire [7:0] q1, q2, q3;
  my_dff8 ff1 (.clk(clk), .d(d),  .q(q1));
  my_dff8 ff2 (.clk(clk), .d(q1), .q(q2));
  my_dff8 ff3 (.clk(clk), .d(q2), .q(q3));
  always @(*) begin
    case (sel)
      2'd0: q = d;
      2'd1: q = q1;
      2'd2: q = q2;
      2'd3: q = q3;
    endcase
  end
endmodule",
  "directed": [
    {"d": 18, "sel": 0},
    {"d": 52, "sel": 1},
    {"d": 86, "sel": 2},
    {"d": 120, "sel": 3},
    {"d": 154, "sel": 0},
    {"d": 188, "sel": 1},
    {"d": 222, "sel": 2},
    {"d": 240, "sel": 3},
    {"d": 19, "sel": 1},
    {"d": 87, "sel": 2}
  ],
  "hints": {
    "L0": "Think about how a shift register works and how a multiplexer can select between different stages.",
    "L3": "Connect the three my_dff8 instances in series: the first takes d, the second takes the first's output, the third takes the second's output. Use a case statement on sel to assign q to either d, the first flip-flop's output, the second's, or the third's."
  },
  "common_mistakes": [
    "Selecting the wrong flip-flop output for a given sel value (off-by-one).",
    "Forgetting that sel=0 should bypass all flip-flops and output d directly.",
    "Not chaining the flip-flops correctly (e.g., connecting all flip-flop inputs to d).",
    "Misunderstanding the clocked behavior: the flip-flop outputs update only on clock edges, so the delay is in cycles."
  ]
}

